# Now perform BFS to find nodes at exactly depth 4
from collections import deque

def bfs_exact_depth(graph, start, target_depth):
    # Track minimum depth to reach each node
    min_depth = {start: 0}
    queue = deque([start])

    while queue:
        node = queue.popleft()
        current_depth = min_depth[node]

        if current_depth >= target_depth:
            continue

        for neighbor in graph.get(node, []):
            if neighbor not in min_depth:
                min_depth[neighbor] = current_depth + 1
                queue.append(neighbor)

    # Return nodes with exactly target_depth
    result = [node for node, depth in min_depth.items() if depth == target_depth]
    return sorted(result)

# Trace through depths
start_node = "1679091c5a"
for d in range(1, 5):
    nodes_at_d = bfs_exact_depth(graph, start_node, d)
    print(f"Depth {d}: {nodes_at_d}")

# Final result for depth 4
result = bfs_exact_depth(graph, start_node, 4)
print(f"\nFinal Answer: {result}")
